<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import QRCode from 'qrcode'
import { ElMessage, ElMessageBox } from 'element-plus'
import { getPage, post } from '@/api/resources'
import { http, problemMessage } from '@/api/http'
import type { Asset } from '@/types/domain'
import StatusTag from '@/components/StatusTag.vue'
import { formatNumber } from '@/utils/format'

interface Zone { id: string; name: string }
interface Carbon { totalKgCo2e?: number; validCount?: number; missingCount?: number; formula?: string }
const data = ref<{ items: Asset[]; total: number; page: number; pageSize: number }>({ items: [], total: 0, page: 1, pageSize: 20 })
const zones = ref<Zone[]>([])
const carbon = ref<Carbon>()
const loading = ref(true)
const error = ref('')
const search = ref('')
const category = ref('')
const dialog = ref(false)
const edit = ref<Asset>()
const submitting = ref(false)
const qrDialog = ref(false)
const qrImage = ref('')
const qrName = ref('')
const form = reactive({ id: '', code: '', name: '', category: 'Sensor', zoneId: '', longitude: 121.43, latitude: 31.19, status: 'Active', publicDescription: '', publicCode: '', version: 0, device: { code: '', type: 'Soil', enabled: true, model: '', manufacturer: '' }, plant: { species: '', diameterCm: undefined as number | undefined, heightM: undefined as number | undefined, health: 'Healthy' }, facility: { kind: '', specification: '', quantity: 1 } })
const isSensor = computed(() => form.category === 'Sensor')
const isPlant = computed(() => form.category === 'Plant')
function publicCodeFor(code: string): string { return `P-${code.trim().toUpperCase().replace(/\s+/g, '-')}` }
function updatePublicCode(): void { if (!edit.value) form.publicCode = publicCodeFor(form.code) }
async function load(): Promise<void> { loading.value = true; error.value = ''; try { const [assets, park, carbonData] = await Promise.all([getPage<Asset>('/assets', { page: data.value.page, pageSize: data.value.pageSize, search: search.value || undefined, category: category.value || undefined }), http.get<{ zones: Zone[] }>('/platform/park'), http.get<Carbon>('/assets/carbon')]); data.value = assets; zones.value = park.data.zones ?? []; carbon.value = carbonData.data } catch (exception) { error.value = problemMessage(exception) } finally { loading.value = false } }
function reset(item?: Asset): void { edit.value = item; Object.assign(form, { id: item?.id ?? '', code: item?.code ?? '', name: item?.name ?? '', category: item?.category ?? 'Sensor', zoneId: item?.zoneId ?? '', longitude: item?.longitude ?? 121.43, latitude: item?.latitude ?? 31.19, status: item?.status ?? 'Active', publicDescription: item?.publicDescription ?? '', publicCode: item?.publicCode ?? '', version: item?.version ?? 0, device: { code: String(item?.device?.code ?? ''), type: String(item?.device?.type ?? 'Soil'), enabled: Boolean(item?.device?.enabled ?? true), model: String(item?.device?.model ?? ''), manufacturer: String(item?.device?.manufacturer ?? '') }, plant: { species: String(item?.plant?.species ?? ''), diameterCm: item?.plant?.diameterCm as number | undefined, heightM: item?.plant?.heightM as number | undefined, health: String(item?.plant?.health ?? 'Healthy') }, facility: { kind: String(item?.facility?.kind ?? ''), specification: String(item?.facility?.specification ?? ''), quantity: Number(item?.facility?.quantity ?? 1) } }); dialog.value = true }
async function save(): Promise<void> { if (!form.code.trim() || !form.name.trim() || !form.zoneId) return ElMessage.warning('请填写资产编码、名称和区域。'); if (!form.publicCode) updatePublicCode(); if (!form.publicCode) return ElMessage.warning('请输入有效资产编码以生成公开物码。'); submitting.value = true; try { const payload = { ...form, device: isSensor.value ? form.device : undefined, plant: isPlant.value ? form.plant : undefined, facility: !isSensor.value && !isPlant.value ? form.facility : undefined }; if (edit.value) await http.put(`/assets/${form.id}`, payload); else await post('/assets', payload); dialog.value = false; await load(); ElMessage.success('资产台账已保存。') } catch (exception) { ElMessage.error(problemMessage(exception)) } finally { submitting.value = false } }
async function retire(item: Asset): Promise<void> { try { await ElMessageBox.confirm(`退役“${item.name}”后不可再控制或写入新遥测，历史仍会保留。确定退役？`, '确认退役', { type: 'warning' }); await post(`/assets/${item.id}/retire`); await load(); ElMessage.success('资产已退役。') } catch (exception) { if (exception !== 'cancel' && exception !== 'close') ElMessage.error(problemMessage(exception)) } }
async function showQr(item: Asset): Promise<void> { if (!item.publicCode) return ElMessage.warning('该资产未配置公开码。'); try { qrName.value = item.name; qrImage.value = await QRCode.toDataURL(`${window.location.origin}/visitor/assets/${item.publicCode}`, { width: 280, margin: 2, color: { dark: '#123d35', light: '#ffffff' } }); qrDialog.value = true } catch (exception) { ElMessage.error(problemMessage(exception, '二维码生成失败。')) } }
function changePage(page: number): void { data.value.page = page; void load() }
onMounted(() => { void load() })
</script>
<template><div class="page"><div class="page-heading"><div><h1>资产信息管理</h1><p>统一维护传感器、基础设施与活植物主数据；资产编码和公开物码创建后不可变更。</p></div><el-button type="primary" @click="reset()">新增资产</el-button></div><section class="asset-stats"><article class="surface"><span>资产总数</span><b>{{ data.total }}</b></article><article class="surface"><span>植物碳储量估算</span><b>{{ formatNumber(carbon?.totalKgCo2e, 1) }} <small>kg CO₂e</small></b><p>有效 {{ carbon?.validCount ?? 0 }} 株，缺失 {{ carbon?.missingCount ?? 0 }} 株</p></article><article class="surface formula"><b>{{ carbon?.formula || 'B=.1D²H · C=B×.5×44/12' }}</b><p>仅为演示储量估算，非年度碳汇、交易或官方核算。</p></article></section><section class="surface toolbar"><el-input v-model="search" clearable placeholder="搜索资产编码或名称" @keyup.enter="data.page = 1; load()" /><el-select v-model="category" clearable placeholder="资产类别" @change="data.page = 1; load()"><el-option label="传感器设备" value="Sensor" /><el-option label="基础设施" value="Facility" /><el-option label="活植物" value="Plant" /></el-select><el-button @click="data.page = 1; load()">查询</el-button></section><el-alert v-if="error" type="error" :title="error" :closable="false" /><section class="surface table-panel" v-loading="loading"><el-table :data="data.items" empty-text="暂无资产"><el-table-column prop="code" label="资产编码" min-width="135" /><el-table-column prop="name" label="名称" min-width="150" /><el-table-column prop="category" label="类别" width="110" /><el-table-column label="状态" width="110"><template #default="scope"><StatusTag :status="scope.row.status" /></template></el-table-column><el-table-column prop="publicCode" label="公开物码" min-width="130" /><el-table-column label="操作" width="260" fixed="right"><template #default="scope"><el-button link type="primary" @click="$router.push(`/admin/assets/${scope.row.id}`)">详情</el-button><el-button link type="primary" @click="reset(scope.row)">编辑</el-button><el-button link type="success" @click="showQr(scope.row)">二维码</el-button><el-button link type="danger" :disabled="scope.row.status === 'Retired'" @click="retire(scope.row)">退役</el-button></template></el-table-column></el-table><el-pagination v-if="data.total > data.pageSize" layout="prev, pager, next" :current-page="data.page" :page-size="data.pageSize" :total="data.total" @current-change="changePage" /></section><el-dialog v-model="dialog" :title="edit ? '编辑资产' : '新增资产'" width="760px" :close-on-click-modal="false"><el-form label-position="top"><div class="form-row"><el-form-item label="资产编码" required><el-input v-model="form.code" :disabled="!!edit" @input="updatePublicCode" /></el-form-item><el-form-item label="公开物码"><el-input v-model="form.publicCode" disabled /></el-form-item></div><div class="form-row"><el-form-item label="资产名称" required><el-input v-model="form.name" /></el-form-item><el-form-item label="资产类别" required><el-select v-model="form.category" :disabled="!!edit"><el-option label="传感器设备" value="Sensor" /><el-option label="基础设施" value="Facility" /><el-option label="活植物" value="Plant" /></el-select></el-form-item></div><div class="form-row"><el-form-item label="所在区域" required><el-select v-model="form.zoneId"><el-option v-for="zone in zones" :key="zone.id" :label="zone.name" :value="zone.id" /></el-select></el-form-item><el-form-item label="状态"><el-select v-model="form.status"><el-option label="启用" value="Active" /><el-option label="退役" value="Retired" /></el-select></el-form-item></div><div class="form-row"><el-form-item label="经度"><el-input-number v-model="form.longitude" :precision="6" /></el-form-item><el-form-item label="纬度"><el-input-number v-model="form.latitude" :precision="6" /></el-form-item></div><el-form-item label="游客公开介绍"><el-input v-model="form.publicDescription" type="textarea" :rows="2" /></el-form-item><template v-if="isSensor"><div class="form-row"><el-form-item label="设备编码" required><el-input v-model="form.device.code" /></el-form-item><el-form-item label="设备类型" required><el-select v-model="form.device.type"><el-option v-for="type in ['Soil','WaterLevel','WaterQuality','Toilet','Noise','Weather','Pest','Camera','Irrigation','Lamp','Broadcast']" :key="type" :value="type" /></el-select></el-form-item></div><el-form-item><el-checkbox v-model="form.device.enabled">启用台账设备</el-checkbox></el-form-item></template><template v-else-if="isPlant"><div class="form-row"><el-form-item label="树种"><el-input v-model="form.plant.species" /></el-form-item><el-form-item label="健康状态"><el-input v-model="form.plant.health" /></el-form-item></div><div class="form-row"><el-form-item label="胸径（cm）"><el-input-number v-model="form.plant.diameterCm" :min="0" /></el-form-item><el-form-item label="树高（m）"><el-input-number v-model="form.plant.heightM" :min="0" /></el-form-item></div></template><template v-else><div class="form-row"><el-form-item label="设施类别"><el-input v-model="form.facility.kind" /></el-form-item><el-form-item label="数量"><el-input-number v-model="form.facility.quantity" :min="1" /></el-form-item></div><el-form-item label="规格"><el-input v-model="form.facility.specification" /></el-form-item></template><el-button type="primary" :loading="submitting" @click="save">保存资产</el-button></el-form></el-dialog><el-dialog v-model="qrDialog" title="公开物码二维码" width="380px"><div class="qr"><img :src="qrImage" :alt="`${qrName} 公开物码`" /><p>{{ qrName }}</p><a :href="qrImage" :download="`${qrName}-二维码.png`" class="el-button el-button--primary">下载二维码 PNG</a></div></el-dialog></div></template>
<style scoped>.asset-stats { display:grid; grid-template-columns:1fr 1.2fr 1.5fr; gap:16px; margin-bottom:18px; }.asset-stats article { padding:17px; }.asset-stats span,.asset-stats p { color:#758681; font-size:12px; }.asset-stats b { display:block; margin-top:7px; color:#276855; font-size:22px; }.asset-stats b small { font-size:12px; font-weight:500; }.asset-stats p { margin:6px 0 0; }.asset-stats .formula b { font-size:14px; }.table-panel { padding:18px; margin-top:16px; }.form-row { display:grid; grid-template-columns:1fr 1fr; gap:14px; }.qr { text-align:center; }.qr img { width:280px; height:280px; }.qr p { margin:8px 0 3px; color:#34564d; }</style>
